def enumerate_count(file_name):
    count = 0
    with open(file_name) as stream:
        for count, _ in enumerate(stream, 1):
            pass
    return count

def iter_count(file_name):
    from itertools import takewhile, repeat
    buffer = 1024 * 1024
    with open(file_name, 'rb') as stream:
        blocks = takewhile(
            lambda block: block,
            (stream.read(buffer) for _ in repeat(None))
        )
        return sum(block.count(b'\n') for block in blocks)
